TLM.f("Sancti/01-31",{"officium":"S. Joannis Bosco Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","sections":{"Introitus":[{"k":"ref","la":"3 Reg 4:29"},{"k":"text","la":"Dedit illi Deus sapiéntiam, et prudéntiam multam nimis, et latitúdinem cordis, quasi arénam quæ est in líttore maris."},{"k":"ref","la":"Ps 112:1"},{"k":"text","la":"Laudáte, púeri, Dóminum, laudáte nomen Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dedit illi Deus sapiéntiam, et prudéntiam multam nimis, et latitúdinem cordis, quasi arénam quæ est in líttore maris."}],"Oratio":[{"k":"text","la":"Deus, qui sanctum Joánnem Confessórem tuum adolescentium patrem et magístrum excitásti, ac per eum, auxiliatríce Vírgine María, novas in Ecclésia tua famílias floréscere voluísti: concéde, quǽsumus; ut eódem caritátis igne succénsi, ánimas quærere, tibíque soli servíre valeámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses."},{"k":"ref","la":"Philipp 4:4-9"},{"k":"text","la":"Fratres: Gaudéte in Dómino semper: íterum dico, gaudéte. Modéstia vestra nota sit ómnibus homínibus: Dóminus prope est. Nihil sollíciti sitis; sed in omni oratióne et obsecratióne, cum gratiárum actióne, petitiónes vestræ innotéscant apud Deum. Et pax Dei quæ exsúperat omnem sensum, custódiat corda vestra et intelligéntias vestras, in Christo Jesu. De cétero, fratres, quæcúmque sunt vera, quæcúmque púdica, quæcúmque justa, quæcúmque sancta, quæcúmque amabília, quæcúmque bonæ famæ, si qua virtus, si qua laus disciplínæ, hæc cogitáte. Quæ et didicístis, et accepístis, et audístis, et vidístis in me, hæc agite: et Deus pacis erit vobíscum."}],"Graduale":[{"k":"ref","la":"Ps 36:3-5"},{"k":"text","la":"Spera in Dómino, et fac bonitátem, et inhábita terram, et pascéris in divítiis ejus."},{"k":"text","la":"Delectáre in Dómino, et dabit tibi petitiónes cordis tui; revéla Dómino viam tuam et spera in eo, et ipse fáciet. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 73:21"},{"k":"text","la":"Pauper et inops laudábunt nomen tuum. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 73:21"},{"k":"text","la":"Pauper et inops laudábunt nomen tuum. Allelúja."},{"k":"ref","la":"Ps 35:9"},{"k":"text","la":"Inebriabúntur ab ubertáte domus tuæ: et torrénte voluptátis tuæ potábis eos. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 60:4-6"},{"k":"text","la":"Factus es spes mea, Dómine: turris fortitúdinis a fácie inimíci."},{"k":"text","la":"Inhabitábo in tabernáculo tuo in sǽcula: prótegar in velaménto alárum tuárum.","mark":"V"},{"k":"text","la":"Quóniam tu, Deus, exaudísti oratiónem meam: dedísti hereditátem timéntibus nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 18:1-5"},{"k":"text","la":"In illo témpore: Accessérunt discípuli ad Jesum dicéntes: Quis, putas, major est in regno cælórum? Et ádvocans Jesus párvulum, státuit eum in médio eórum, et dixit: Amen dico vobis, nisi convérsi fueritis, et efficiámini sicut párvuli, non intrábitis in regnum cœlórum. Quicúmque ergo humiliáverit se sicut párvulus iste, hic est major in regno cœlórum. Et qui suscéperit unum párvulum talem in nómine meo, me súscipit."}],"Offertorium":[{"k":"ref","la":"Ps 33:12"},{"k":"text","la":"Veníte, fílii, audíte me: timórem Dómini docébo vos."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, oblatiónem mundam salutáris Hóstiæ, et præsta: ut, te in ómnibus et super ómnia diligéntes, in glóriæ tuæ laudem vívere mereámur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Rom 4:18"},{"k":"text","la":"Contra spem in spem crédidit, ut fíeret pater multárum géntium, secúndum quod dictum est ei."}],"Postcommunio":[{"k":"text","la":"Córporis et Sánguinis tui, Dómine, mystério satiátis, concéde, quǽsumus; ut, intercedénte sancto Joánne Confessóre tuo, in gratiárum semper actióne maneámus:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"500dc1e808ed6c6d":{"t":"1* Kr 4, 29, Ps 112, 1\n(1* Kr 4, 29) Dao mu je Gospodin veliku mudrost i razboritost i dobrohotnost poput pijeska na obali morskoj. (Ps 112, 1) Hvalite, djeco, Gospodina, hvalite ime Gospodnje.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(1* Kr 4, 29) Dao mu je Gospodin veliku mudrost i razboritost i dobrohotnost poput pijeska na obali morskoj. [* Vulgata Sixto-Clementina sadrži četiri knjige o kraljevima, od kojih se prve dvije u drugim novijim izdanjima označavaju kao knjige o Samuelu: I Reg, II Reg, III Reg, IV Reg odgovaraju 1 Sam, 2 Sam, 1 Kr, 2 Kr]","kn":"(Kr, III. 4, 29). Dao mu je Gospodin 'OSobito veliku mudrost i razboritost i širokogrudnost poput pijeska na obali morskoj. (Ps. 112, 1) Hvalite, djeco. Gospodina, hvalite ime Gospodnje. Slava Ocu. Dao mu je Gospodin.","knRef":"Kniewald 1942, str. 494–495 (snimka 248) (OCR)"},"89208dba64db57bf":{"t":"<i>Pomolimo se</i>.\nBože, koji si svetog Ivana, svoga priznavaoca, potaknuo da bude otac i učitelj mladeži i da uz pomoć Djevice Marije osnuje nove družbe u tvojoj Crkvi, dopusti, molimo, da raspaljeni istim ognjem ljubavi uzmognemo tražiti duše i tebi samom služiti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si sv. Ivana, svoga priznavaoca, potaknuo da bude otać i učitelj omladine, i da uz pomoć blažene Djevice Marije osnuje nove družbe u Tvojoj Crkvi, dopusti, molimo, da, užareni istim ognjem ljubavi uzmognemo tražiti duše i Tebi samomu služiti, po G. a.","knRef":"Kniewald 1942, str. 494–495 (snimka 248) (OCR)"},"74e93cc1af743832":{"t":"Fil 4, 4-9\nČitanje Poslanice bl. Pavla apostola Filipljanima. Braćo! Radujte se uvijek u Gospodinu. Opet kažem: Radujte se! Vaša smjernost neka bude poznata svim ljudima! Gospodin je blizu. Ništa se ne uznemirujte, nego sve svoje molbe očitujte pred Bogom po molitvi i prošnji sa zahvalom. I mir Božji koji nadvisuje svaki um neka čuva vaša srca i vaše misli u Isusu Kristu. Uostalom, braćo, pazite na sve što je iskreno i pošteno, pravedno, sveto, ljubežljivo, dobra glasa, što je uopće kreposno i pohvalno u vršenju dužnosti. Radite kako ste naučili i primili, čuli i vidjeli od mene, i Bog će mira biti s vama.","kn":"Čitanje poslanice bi. Pavla apostola lilipljanima (4, 4-9). Braćo! Radujte se uvijek u Gospodinu, opet kažem; Radujte se! Vaša .smjernost neka bude poznata svim ljudima! Gospodin je blizu. Ništa se ne uznemarujte, nego sve svoje molbe očitujte pred Bogom po molitvi i prošnji sa zahvalom. I mir Božji, koji nadvisuje svaki um, neka čuva vaša srca i vaše misli u Isusu Kristu. U ostalom, braćo, pazite sve, što je iskreno, pošteno, pravedno, sveto, Iju- bežljiV'O, dobra glasa, što je uopće kreposno i pohvalno u vršenju dužnosti. Eadite, kako ste naučili i primili, čuli i vidjeli od mene, i Bog će mira biti B vama.","knRef":"Kniewald 1942, str. 494–495 (snimka 248) (OCR)"},"8ad72ad60d1b5557":{"t":"Ps 36, 3-5\nUzdaj se u Gospodina i čini dobro, dok stanuješ na zemlji, i uživat ćeš dobra zemaljska. Služi Gospodinu i dat će ti što ti srce želi. Otkrij Gospodinu svoje putove i uzdaj se u njega, i on će ti pomoći.\n\nPs 73, 21\n<i>Aleluja</i>, <i>aleluja</i>.\nSiromah će i ubogi hvaliti tvoje ime. <i>Aleluja</i>.","v":"eum → eo","kn":"(Ps. 36, 3-5). Uzdaj se u Gospodina i čini dobro stanujući na zemlji i uživat ćeš dobra zemaljska. Služi Go^dinu ,i dat će ti ono, što Ti srce želi: otkrij Gospodinu putove svoje i uzdaj se u njega, a on će Ti pomoći.\n\nAleluja, aleluja. (Ps. 73, 21) Siromah će i neimuonik hvaliti ime Tvoje, aleluja.","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"},"cd98b15fff32d4ca":{"t":"Mt 18, 1-5\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme, pristupe učenici k Isusu i upitaju ga: Što misliš, tko je najveći u nebeskom kraljevstvu? Isus nato pozva jedno malo dijete, postavi ga pred njih i reče: Zaista vam kažem: ako se ne obratite i ne postanete kao djeca, nećete ući u nebesko kraljevstvo. Dakle, tko se ponizi kao ovo dijete, taj je najveći u nebeskom kraljevstvu. I još vam kažem: tko radi mene primi jedno dijete kao što je ovo, mene prima.","kn":"t Slijedi sv. evanđelje po Mateju (18, 1-5). u ono vrijeme pristupiše učenici k Isusu govoreći: Tko je dakle najveći u kraljevstvu nebeskom? Tada pozva IsiK dijete, postavi ga među njih i reče: Zaista vam kažan: Ako se ne obratite i ne budete kao djeca, ne ćete ući u kraljevstvo nebesko. Koji se dakle ponizi kao ovo dijete, onaj je najveći u kraljevstvu nebeskom. I tko primi jedno takvo dijete U moje ime, mene prima.","knRef":"Kniewald 1942, str. 574–575 (snimka 288) (OCR)"},"a3dbd4092e2a688f":{"t":"Ps 33, 12\nDođite, sinovi, čujte me! Naučit ću vas strahu Gospodnjemu.","kn":"(Ps. 233, 12). Dođite, sinci, čujte me, učit ću vas strahu Gospodnjem.","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"},"44300f796b546512":{"t":"Primi, Gospodine, čisti prinos spasonosne žrtve i daj da te u svemu i nada sve ljubimo i da zaslužimo živjeti na čast tvoje slave.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Taj.oa. Primi, Go.sipodine, čisti prinos spasonosiae žrtve i podaj, da Te u svemu i nada sve ljubimo i da zaslužimo živjeti na čast .slave Tvoje, po G. n.","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"9c07d51e36553bee":{"t":"Rim 4, 18\nProtiv nade vjerovao je i nadao se da će biti otac mnogih naroda, kao što mu je bilo rečeno.","kn":"(Rim. 4, 18). Protiv nade je povjerovao i nadao se. da će biti otac mnogim narodima, kao što mu je bilo rečeno.","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"},"ddfb9b1f4eb41949":{"t":"<i>Pomolimo se</i>.\nDopusti, molimo, Gospodine, da ti uvijek budemo zahvalni po zagovoru svetog Ivana, tvoga priznavaoca, kad smo nahranjeni tajnom tijela i krvi tvoje:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → tuo","kn":"Poprioesna. Dopusti, molimo, Gospodine, da nahranjeni tajnom Tijela i Krvi Tvoje, po zagovoru svetog Ivana, priznavaoca Tvoga, ustrajemo uvijek u zahvaljivamju, koji živiš i kreljuješ . . .","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"},"c8e7d12b60c44002":{"t":"Ps 36, 3-5\nUzdaj se u Gospodina i čini dobro, dok stanuješ na zemlji, i uživat ćeš dobra zemaljska. Služi Gospodinu i dat će ti što ti srce želi. Otkrij Gospodinu svoje putove i uzdaj se u njega, i on će ti pomoći.\n\nPs 60, 4-6\nTi si, Gospodine, moja nada i moja tvrđava pred licem neprijatelja, Stanovat ću u tvojemu domu dovijeka, štitit će me sjena tvojih krila. Jer ti si, Bože, uslišio moju molitvu i dao si baštinu onima koji časte tvoje ime.","v":"eum → eo","kn":"(Ps. 36, 3-5). Uzdaj se u Gospodina i čini dobro stanujući na zemlji i uživat ćeš dobra zemaljska. Služi Go^dinu ,i dat će ti ono, što Ti srce želi: otkrij Gospodinu putove svoje i uzdaj se u njega, a on će Ti pomoći.\n\n; 'Ti si, Gospodine, nada moja i tvrđava moja pred licem neprijatelj evim. Stanovat ću u domu Tvojemu dovijeka, štitit će me sjena krila Tvojih. Jer Ti si. Bože, uslišao moju molitvu i dao si baštinu onima, koji časte ime Tvoje.","knRef":"Kniewald 1942, str. 496–497 (snimka 249) (OCR)"}}});
